use vstd::prelude::*;

verus! {
    /// reverse takes a slice `a` of length n and returns
    /// a new Vec of length n whose elements are in reverse order.
    fn reverse(a: &[i32]) -> Vec<i32>
        ensures
            // The output has the same length…
            result.len() == a.len(),
            // …and for every valid index i it holds
            //   result[i] == a[n-1-i]
            forall |i: usize| i < a.len() ==> result[i] == a[a.len() - 1 - i],
    {
        let mut result = Vec::with_capacity(a.len());
        let mut idx: usize = 0;
        // Build result by pushing a[n-1-idx] one at a time.
        while idx < a.len()
            invariant
                // idx never exceeds the slice length
                idx <= a.len(),
                // we've pushed exactly idx elements so far
                result.len() == idx,
                // and those pushed elements satisfy the reversal
                forall |j: usize| j < idx
                    ==> result[j] == a[a.len() - 1 - j],
            decreases a.len() - idx,
        {
            // push the next element in reverse order
            result.push(a[a.len() - 1 - idx]);
            idx += 1;
        }
        result
    }
}

fn main() {
    // you can test it here if you like
    let x = vec![1,2,3,4];
    let y = reverse(&x);
    assert!(y == vec![4,3,2,1]);
}